assignment.solution:
function totalAfterDiscount(prices, discount) {
  return prices
    .map(price => price * (1 - discount / 100))
    .reduce((sum, price) => sum + price, 0);
}

console.log(totalAfterDiscount([10, 20, 30], 10)); // 54

