  // your code here
}

console.log(sumOfSquaresOfEvens([1, 2, 3, 4, 5])); // 20 (2*2 + 4*4)

assignment.solution:
function sumOfSquaresOfEvens(nums) {
  return nums
    .filter(n => n % 2 === 0)
    .map(n => n * n)
    .reduce((sum, n) => sum + n, 0);
}

console.log(sumOfSquaresOfEvens([1, 2, 3, 4, 5])); // 20

